module async_fifo #(parameter WIDTH = 8, parameter DEPTH = 8)
  (input wclk, input wrst_n, input winc, input [WIDTH-1:0] wdata, output wfull,
   input rclk, input rrst_n, input rinc, output [WIDTH-1:0] rdata, output rempty);

  localparam ADDR_WIDTH = $clog2(DEPTH);
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  reg [ADDR_WIDTH:0] wptr_bin;
  reg [ADDR_WIDTH:0] wptr_gray;
  reg [ADDR_WIDTH:0] rptr_gray_w;
  reg [ADDR_WIDTH:0] rptr_gray_sync1_w;
  reg [ADDR_WIDTH:0] rptr_gray_sync2_w;
  reg [ADDR_WIDTH:0] rptr_bin_w;

  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_bin <= 0;
      wptr_gray <= 0;
      rptr_gray_sync1_w <= 0;
      rptr_gray_sync2_w <= 0;
      rptr_bin_w <= 0;
    end else begin
      rptr_gray_sync1_w <= rptr_gray_w;
      rptr_gray_sync2_w <= rptr_gray_sync1_w;
      rptr_bin_w <= (rptr_gray_sync2_w >> 1) ^ rptr_gray_sync2_w;
      if (winc && !wfull) begin
        mem[wptr_bin[ADDR_WIDTH-1:0]] <= wdata;
        wptr_bin <= wptr_bin + 1;
        wptr_gray <= (wptr_bin >> 1) ^ wptr_bin;
      end
    end
  end

  assign wfull = (wptr_gray[ADDR_WIDTH-1:0] == {~rptr_gray_sync2_w[ADDR_WIDTH-1:0]});

  reg [ADDR_WIDTH:0] rptr_bin;
  reg [ADDR_WIDTH:0] rptr_gray;
  reg [ADDR_WIDTH:0] wptr_gray_sync1_r;
  reg [ADDR_WIDTH:0] wptr_gray_sync2_r;
  reg [ADDR_WIDTH:0] wptr_bin_r;
  reg [WIDTH-1:0] rdata_reg;

  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rptr_bin <= 0;
      rptr_gray <= 0;
      wptr_gray_sync1_r <= 0;
      wptr_gray_sync2_r <= 0;
      wptr_bin_r <= 0;
      rdata_reg <= 0;
    end else begin
      wptr_gray_sync1_r <= wptr_gray;
      wptr_gray_sync2_r <= wptr_gray_sync1_r;
      wptr_bin_r <= (wptr_gray_sync2_r >> 1) ^ wptr_gray_sync2_r;
      if (rinc && !rempty) begin
        rdata_reg <= mem[rptr_bin[ADDR_WIDTH-1:0]];
        rptr_bin <= rptr_bin + 1;
        rptr_gray <= (rptr_bin >> 1) ^ rptr_bin;
      end
    end
  end

  assign rdata = rdata_reg;
  assign rempty = (rptr_bin[ADDR_WIDTH-1:0] == wptr_bin_r[ADDR_WIDTH-1:0]);
  assign rptr_gray_w = rptr_gray;

endmodule
